  "Card": "import React, {useState} from 'react';\nimport * as U from '@fiveplusone/ui';\nimport {\r\n  Plus,\r\n  ArrowUpRight,\r\n  Download,\r\n  Settings,\r\n  Search,\r\n  Bell,\r\n  FileText,\r\n  BookOpen,\r\n  MoreHorizontal,\r\n  Heart,\r\n  Copy,\r\n  Check,\r\n  Mail,\r\n  ArrowRight,\r\n  LayoutGrid,\r\n  PanelLeft,\r\n  Sun,\r\n  Moon,\r\n  Sparkles,\r\n} from \"lucide-react\";\nimport '@fiveplusone/ui/styles.css';\nexport function Example(){\n\nreturn ((\r\n      <U.Card>\r\n        <U.Badge tone=\"accent\">学习笔记</U.Badge>\r\n        <h3>让知识彼此连接</h3>\r\n        <p className=\"fp-muted\">从零散的想法，到清晰的理解。</p>\r\n        <U.Link href=\"#/examples\">继续阅读 ↗</U.Link>\r\n      </U.Card>\r\n    ));\n}",
